INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.90.0',
  '2026-09-18',
  'Пульт ТВ: музыка на паузе, режимы музыки, перемотка стрелками',
  E'Под видео появилась галочка «Музыка на паузе». Если она стоит, то стоит поставить видео на паузу — заиграет музыка, а как только видео снова пошло — музыка замолкает и в следующий раз продолжит с того же места. Если музыку ещё не выбирали, играет первая музыкальная папка. Галочка помнится, пока открыта медиатека.\n\nНа панели музыки два новых переключателя. Как играть: «➡ Один раз» — очередь до конца и стоп, «🔁 Весь плейлист» — по кругу, «🔂 Один трек» — текущий трек снова и снова. Порядок — иконкой: 🔢 по порядку или 🔀 вперемешку (текущий трек доигрывает, остальные прозвучат по разу, а «Играть всё» начнёт со случайного). Выбор запоминается.\n\nКогда видео развёрнуто во весь экран, стрелки влево и вправо на пульте мотают на 30 секунд назад и вперёд, сверху на секунду видно, куда перемотали.',
  E'player.html. «Музыка на паузе» — кнопка-галочка в #bar (actions.musicpause), sessionStorage htv.musicOnPause. Слушатель pause у видео запускает музыку, только когда смотрят (watchingVideo: есть src, не ended, в визуальном режиме открыт плеер или theater): паузы, которые ставит сама страница — выход в каталог (leavePlayer снимает класс player до pause()), «⏹» (src снят), конец серии, включение музыки руками (a уже играет), — не в счёт. Событие pause асинхронное, поэтому pauseMusicStart перепроверяет v.paused. Пустая очередь — первая плитка catalog.music (или /api/catalog в режиме «Файлы») и её треки через /api/browse; пока грузится, снова проверяются галочка и паузы. Слушатель play у видео ставит музыку на паузу.\n\nРежимы музыки: musicRepeat once|all|one и musicShuffle в localStorage (htv.mrepeat, htv.mshuffle); кнопки .mmode в #vmusic и #mbar. Очередь хранит порядок morder (индексы) и позицию mpos, mi = morder[mpos]; buildOrder(current) держит текущий трек первым при перемешивании. musicStep(dir, auto): конец трека в режиме one — повтор; за краем очереди — стоп (once/one) или круг (all), новый круг вперемешку не начинается с только что сыгранного. Все прежние mi++/mi-- заменены на musicStep, в состояние для пульта уходит mpos.\n\nВо весь экран: стрелки влево/вправо — actions.back/fwd (повтор зажатой разрешён), вверх/вниз гасятся (ходить по скрытым кнопкам незачем); #osd показывает позицию или ⏸/▶ 1,5 с.\n\nНайдено при проверке: чтение store до его объявления (TDZ) роняло весь скрипт страницы — пойман по консоли до выкладки, настройки читаются после объявления store. Проверено в браузере на локальном агенте с музыкальной библиотекой (воспроизведение подменено: фоновая вкладка медиа не играет): пауза с галочкой и без, возврат к видео, повторная пауза продолжает тот же трек, выход из плеера и снятие галочки, включение галочки на паузе; once/all/one вперёд и назад, перемешивание с сохранением текущего трека; стрелки, повтор, вверх-вниз, OK и Escape во весь экран и вне его. После выкладки страница на res-i3 открывается без ошибок.'
);
